import json,hashlib
p='/workspace/scratch/volume4/batch359-368.json';d=json.load(open(p))
def page(n,rows):
 ps=[]
 for i,(ar,ru) in enumerate(rows,1):
  sid=f'v4-p{n}-{i:02}';ps.append(dict(id=sid,ar=ar,sha256=hashlib.sha256(ar.encode()).hexdigest(),witness='uploaded_2019_control_pdf',source_complete=True))
  d['units'].append(dict(id=sid+'-ru',source_ids=[sid],printed_pages=[n],ar=ar,ru=ru,draft_status='draft',print_collation='control_image_read',independent_human_review=False))
 d['pages'].append(dict(printed_page=n,pdf_leaf=n,witness_status='control_print_visually_read',publisher_footnote_text_imported=False,paragraphs=ps))
page(366,[
('يظهر منه. والتلبيس: يشبه التعمية والتخليط، ومنه قوله: {ولا تلبسوا الحق بالباطل} [البقرة: ٤٢].', 'напрашивается из сказанного. Тальбис сходен с затемнением и смешением. Отсюда слова Всевышнего: {ولا تلبسوا الحق بالباطل} — «Не смешивайте истину с ложью» [2:42].'),
('فصل', 'Раздел'),
('قال الشيخ: «وهو اسم لثلاث معان، أولها: تلبيس الحق بالكون على أهل التفرقة، وهو تعليقه الكوائن بالأسباب والأماكن والأحايين، وتعليقه المعارف بالوسائط، والقضايا بالحجج، والأحكام بالعلل، والانتقام بالجنايات، والمثوبة بالطاعات، وأخفى الرضا والسخط اللذين يوجبان الفصل والوصل، ويظهران السعادة والشقاوة».', 'Шейх сказал: «Это имя трёх смыслов. Первый — тальбис Истинного посредством сотворённого мира для людей разделённого восприятия. Он состоит в том, что Он связывает происходящие события с причинами, местами и временами, познания — с промежуточными причинами, судебные решения — с доказательствами, установления — с основаниями, возмездие — с преступлениями, а награду — с деяниями покорности. Он скрыл довольство и гнев, которые влекут за собой отлучение и соединение и обнаруживают счастье и несчастье».'),
('شيخ الإسلام رحمه الله حبيبنا، والحق أحب إلينا منه، وكان شيخ الإسلام ابن تيمية يقول: عمله خير من علمه. وصدق رحمه الله، فسيرته في الأمر بالمعروف والنهي عن المنكر وجهاد أهل البدع لا يشق له فيها غبار، وله المقامات المشهورة في نصر الله ورسوله، وأبى الله أن يكسو ثوب العصمة لغير الصادق المصدوق الذي لا ينطق عن الهوى. وأخطأ رحمه الله في هذا الباب لفظا ومعنى.', 'Шейх ислама, да помилует его Аллах, любим нами, однако истина нам дороже него. Шейх ислама Ибн Таймийя говорил: «Его дела лучше его знания». И он сказал правду, да помилует его Аллах: в повелении одобряемого, запрещении порицаемого и борьбе с приверженцами нововведений никто не мог угнаться за ним. Известны его деяния в поддержку Аллаха и Его Посланника. Но Аллах не пожелал облечь в одеяние непогрешимости никого, кроме Правдивого, признанного правдивым, который не говорит по прихоти. В этой главе шейх, да помилует его Аллах, ошибся и в словах, и в смысле.'),
('أما اللفظة: فتسمية فعل الله الذي هو حق وصواب وحكمة، وحكمه الذي هو عدل وإحسان، وأمره الذي هو دينه وشرعه = «تلبيسا». فمعاذ الله ثم معاذ الله من هذه التسمية! ومعاذ الله من الرضا بها، والإقرار عليها، والذب عنها، والانتصار لها. ونحن نشهد بالله أن هذا تلبيس على شيخ الإسلام،', 'Что касается слова, то он назвал «тальбисом» деяние Аллаха, которое есть истина, верность и мудрость, Его решение, которое есть справедливость и благодеяние, и Его повеление, которое есть Его религия и Закон. Упаси Аллах, и ещё раз упаси Аллах, от такого названия! Упаси Аллах довольствоваться им, соглашаться с ним, защищать его и отстаивать. Мы свидетельствуем Аллахом, что здесь в заблуждение введён сам шейх ислама,')])
page(367,[
('فالتلبيس وقع عليه، ولا نقول: وقع منه، ولكنه صادق لبس عليه، ولعل متعصبا له يقول: أنتم لا تفهمون كلامه! فنحن نبين مراده على وجهه إن شاء الله، ثم نتبع ذلك بما له وعليه.', 'тальбис постиг его; мы не говорим, что он исходил от него. Он правдивый человек, которого ввели в заблуждение. Возможно, его пристрастный приверженец скажет: «Вы не понимаете его слов!» Мы разъясним то, что он имел в виду, должным образом, если пожелает Аллах, а затем укажем, что в этом верно и что заслуживает возражения.'),
('فقوله: «أولها: تلبيس الحق بالكون على أهل التفرقة»، الحق هاهنا المراد به الرب تعالى، والكون اسم لكل ما سواه، وأهل التفرقة ضد أهل الجمع، وسيأتي معنى الجمع عنده بعد هذا إن شاء الله، فأهل التفرقة الذين لم يصلوا إلى مقام الجمع. وأهل التفرقة عنده لبس عليهم الحق بالباطل، فإنهم لبس عليهم الحق بالكون وهو باطل، وكل شيء ما خلا الله باطل، وأهل التفرقة عندهم الذين غلب عليهم النظر إلى الأسباب حتى غفلوا عن المسبب، ووقفوا معها دونه. و«التلبيس» فعل من أفعال الرب تعالى، وهو سبحانه يضل من يشاء ويهدي من يشاء، ولذلك استدل على هذا المعنى بالآية، وهي قوله: {وللبسنا عليهم ما يلبسون} [الأنعام: ٩] ليعرفك أن هذا الفعل لا يمتنع نسبته إلى الله كما لا يمتنع نسبة الإضلال إليه.', 'В его словах «первый — тальбис Истинного посредством сотворённого мира для людей разделённого восприятия» под Истинным имеется в виду Всевышний Господь, а «сотворённый мир» — имя всего, кроме Него. Люди разделённого восприятия противопоставлены людям собранности. Ниже, если пожелает Аллах, будет разъяснено, что он понимает под собранностью. Люди разделённого восприятия — те, кто не достиг стоянки собранности. По его мнению, для них истина смешана с ложью: Истинный скрыт от них сотворённым миром, а тот тщетен, ибо всё, кроме Аллаха, тщетно. Люди разделённого восприятия в их понимании — те, чьё внимание к причинам возобладало настолько, что они забыли о Создающем причины и остановились на них, не обращаясь к Нему. «Тальбис» здесь отнесён к действиям Всевышнего Господа: Пречистый вводит в заблуждение, кого пожелает, и ведёт верным путём, кого пожелает. Потому шейх и сослался для обоснования этого смысла на аят {وللبسنا عليهم ما يلبسون} — «И Мы запутали бы для них то, что они сами путают» [6:9], чтобы показать тебе: приписывать это действие Аллаху допустимо так же, как допустимо относить к Нему введение в заблуждение.'),
('ووجه هذا التلبيس: أنه سبحانه أضاف الأفعال الصادرة عن محض قدرته ومشيئته إلى أسباب وأزمنة وأمكنة، فلبس الحق سبحانه على أهل التفرقة حيث علق الكوائن ـ وهي الأفعال ـ بالأسباب، فنسبها أهل التفرقة إلى أسبابها، وعموا عن رؤية الحق سبحانه، ففي الحقيقة لا فعل إلا لله. وأهل التفرقة يجهلون ذلك، ويقولون: فعل فلان، وفعل الماء، وفعل الهواء، وفعلت النار.', 'Суть этого тальбиса, по его мысли, в том, что Пречистый отнёс действия, исходящие исключительно из Его могущества и воли, к причинам, временам и местам. Так Пречистый Истинный ввёл людей разделённого восприятия в заблуждение, связав происходящие события, то есть действия, с причинами; они приписали их причинам и ослепли к видению Пречистого Истинного. В действительности же действие принадлежит лишь Аллаху. Люди разделённого восприятия этого не знают и говорят: «Такой-то сделал; вода подействовала; воздух подействовал; огонь подействовал».'),
('وكذلك تعليقه سبحانه المعارف بالوسائط، وهي الأدلة السمعية والعقلية والفطرية، وتعليقه المسموعات والمبصرات والملموسات بآلاتها', 'То же относится к тому, что Пречистый связывает познания с промежуточными причинами — свидетельствами откровения, разума и естества, а слышимое, видимое и осязаемое — с их орудиями')])
page(368,[
('وحواسها، من السمع والبصر والشم والذوق واللمس، فهو سبحانه الخالق لتلك الإدراكات مقارنة لهذه الحواس وعندها، لا بها ولا بقوى مودعة فيها، وهو سبحانه قادر على خلق هذه المعارف بغير هذه الوسائط، فحجب أهل التفرقة بهذه الوسائط عن الفعال سبحانه حقيقة الذي لا فعل في الحقيقة إلا له، فكأنه لبس على أهل التفرقة، أي أضلهم بشهودهم الأسباب، وغيبتهم بها عنه.', 'и чувствами — слухом, зрением, обонянием, вкусом и осязанием. Пречистый создаёт эти восприятия одновременно с этими чувствами и при их наличии, а не посредством них или вложенных в них сил. Он способен создать эти познания и без таких промежуточных причин. Эти промежуточные причины заслонили людей разделённого восприятия от подлинно Действующего, Пречистого, Которому одному в действительности принадлежит действие. Как будто Он ввёл их в заблуждение, то есть сбил их с пути тем, что они созерцают причины и за ними теряют Его из виду.'),
('وكذلك القضايا ـ وهي الوقائع بين العباد ـ علقها بالحجج الموجبة لها، فكل قضاء وحكم لا بد له من حجة يستند إليها، فيحجب صاحب التفرقة بتلك الحجة عن المصدر الأول الذي منه ابتداء كل شيء، ويقف مع الحجة، لا ينظر إلى من حكم بها، وجعلها مظهرا لنفوذ حكمه وقضائه.', 'Так же и судебные решения — то есть дела, возникающие между рабами, — Он связал с доказательствами, которые их обусловливают. Всякому судебному решению и суждению необходимо доказательство, на которое оно опирается. Это доказательство заслоняет от человека разделённого восприятия Первоначальный Источник, от Которого берёт начало всё. Человек останавливается на доказательстве, не взирая на Того, Кто вынес по нему решение и сделал его местом проявления осуществления Своего решения и суда.'),
('وكذلك تعليقه الأحكام بالعلل، وهي المعاني والمناسبات والحكم والمصالح التي لأجلها ثبتت الأحكام، وهو سبحانه واضع تلك المعاني، ومضيف الأحكام إليها، وإنما هي في الحقيقة مضافة إليه سبحانه.', 'То же относится к связыванию установлений с основаниями — смыслами, соответствиями, мудрыми целями и благими интересами, ради которых установления и утверждены. Пречистый — Тот, Кто определяет эти смыслы и относит к ним установления, хотя в действительности они отнесены к Нему, Пречистому.'),
('وكذلك ترتيبه الانتقام على الجنايات، وربطه الثواب بالطاعات، كل ذلك مضاف إليه وحده، لا إلى الجنايات ولا إلى الطاعات، فإضافة ذلك إليها تلبيس على أهل التفرقة.', 'То же относится к тому, что Он устанавливает возмездие за преступления и связывает награду с деяниями покорности. Всё это отнесено к Нему одному, а не к преступлениям и не к деяниям покорности. Поэтому отнесение этого к ним оказывается тальбисом для людей разделённого восприятия.'),
('وموضع التلبيس في ذلك كله أن أهل التفرقة يظنون أنه لولا تلك الوسائط لما وجدت معرفة، ولا وقعت قضية، ولا حكم ولا ثواب، ولا', 'Тальбис во всём этом состоит в том, что люди разделённого восприятия полагают: если бы не эти промежуточные причины, не было бы ни познания, ни судебного дела, ни решения, ни награды, ни')])
json.dump(d,open(p,'w'),ensure_ascii=False,indent=2)
